package com.rulecraft.decisionops.deployment;

import static org.assertj.core.api.Assertions.*;import com.rulecraft.decisionops.catalog.CatalogService;import com.rulecraft.decisionops.catalog.CatalogService.*;import com.rulecraft.decisionops.catalog.domain.*;import com.rulecraft.decisionops.deployment.RuntimeDeploymentService.*;import com.rulecraft.decisionops.deployment.domain.RuntimeDeploymentState;import com.rulecraft.decisionops.expressions.DecisionExpressionService;import com.rulecraft.decisionops.expressions.DecisionExpressionService.ExpressionCommand;import com.rulecraft.decisionops.graph.DecisionGraphService;import com.rulecraft.decisionops.graph.DecisionGraphService.*;import com.rulecraft.decisionops.graph.domain.*;import com.rulecraft.decisionops.identity.domain.*;import com.rulecraft.decisionops.identity.persistence.UserAccountRepository;import com.rulecraft.decisionops.identity.security.RuleCraftPrincipal;import com.rulecraft.decisionops.platform.web.DomainProblemException;import com.rulecraft.decisionops.projects.ProjectService;import com.rulecraft.decisionops.projects.domain.ProjectRole;import com.rulecraft.decisionops.versions.DecisionVersionService;import com.rulecraft.decisionops.versions.DecisionVersionService.CaptureCommand;import com.rulecraft.decisionops.workflow.ApprovalWorkflowService;import com.rulecraft.decisionops.workflow.ApprovalWorkflowService.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.security.crypto.password.PasswordEncoder;import tools.jackson.databind.ObjectMapper;

@SpringBootTest class RuntimeDeploymentIntegrationTest {@Autowired RuntimeDeploymentService deployment;@Autowired ApprovalWorkflowService workflow;@Autowired DecisionVersionService versions;@Autowired DecisionExpressionService expressions;@Autowired DecisionGraphService graphs;@Autowired CatalogService catalog;@Autowired ProjectService projects;@Autowired UserAccountRepository users;@Autowired PasswordEncoder passwords;@Autowired ObjectMapper mapper;@Autowired Clock clock;RuleCraftPrincipal admin;@BeforeEach void actor(){admin=new RuleCraftPrincipal(users.findForLogin("acme-rules","admin@example.test").orElseThrow(),"acme-rules");}
@Test void activatesImmutableArtifactsEvaluatesAndRollsBack(){var fixture=fixture();var first=promote(fixture,"Threshold 700");var deployId=UUID.randomUUID();var active=deployment.deploy(admin,fixture.projectId(),fixture.serviceId(),new DeployCommand(deployId,first.id(),workflow.workflow(admin,fixture.projectId(),fixture.serviceId()).promotion().revision()));assertThat(active.state()).isEqualTo(RuntimeDeploymentState.ACTIVE);assertThat(deployment.deploy(admin,fixture.projectId(),fixture.serviceId(),new DeployCommand(deployId,first.id(),0L)).id()).isEqualTo(active.id());assertThat(evaluate(fixture,710).outputs()).containsEntry("approved",mapper.valueToTree(true));var expression=expressions.find(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId()).orElseThrow();expressions.update(admin,fixture.projectId(),fixture.serviceId(),fixture.nodeId(),new ExpressionCommand(expression.version(),"score >= 800"));assertThat(evaluate(fixture,710).outputs()).containsEntry("approved",mapper.valueToTree(true));var second=promote(fixture,"Threshold 800");var state=deployment.sandbox(admin,fixture.projectId(),fixture.serviceId());var secondActive=deployment.deploy(admin,fixture.projectId(),fixture.serviceId(),new DeployCommand(UUID.randomUUID(),second.id(),state.promotionRevision()));assertThat(secondActive.state()).isEqualTo(RuntimeDeploymentState.ACTIVE);assertThat(evaluate(fixture,710).outputs()).containsEntry("approved",mapper.valueToTree(false));state=deployment.sandbox(admin,fixture.projectId(),fixture.serviceId());assertThat(state.deployments()).extracting(DeploymentView::state).containsExactly(RuntimeDeploymentState.ACTIVE,RuntimeDeploymentState.RETIRED);var rolled=deployment.rollback(admin,fixture.projectId(),fixture.serviceId(),active.id(),new StateCommand(UUID.randomUUID(),state.environment().revision(),"Restore known-good threshold"));assertThat(rolled.state()).isEqualTo(RuntimeDeploymentState.ACTIVE);assertThat(evaluate(fixture,710).outputs()).containsEntry("approved",mapper.valueToTree(true));var detail=deployment.detail(admin,fixture.projectId(),fixture.serviceId(),active.id());assertThat(detail.events()).extracting(RuntimeDeploymentService.EventView::eventType).contains("CREATED","VALIDATION_STARTED","ACTIVATED","SUPERSEDED","REACTIVATED");state=deployment.sandbox(admin,fixture.projectId(),fixture.serviceId());deployment.retire(admin,fixture.projectId(),fixture.serviceId(),active.id(),new StateCommand(UUID.randomUUID(),state.environment().revision(),"Pause local runtime"));assertCode("RC-DEPLOY-NO-ACTIVE",()->evaluate(fixture,710));}
@Test void enforcesPromotionStalenessOwnerActionsAndTenantSafeReads(){var fixture=fixture();assertCode("RC-DEPLOY-NO-PROMOTION",()->deployment.deploy(admin,fixture.projectId(),fixture.serviceId(),new DeployCommand(UUID.randomUUID(),UUID.randomUUID(),0L)));var version=promote(fixture,"Governed baseline");var viewer=member(fixture.projectId(),"viewer",ProjectRole.VIEWER);assertCode("RC-PROJECT-PROMOTE-FORBIDDEN",()->deployment.deploy(viewer,fixture.projectId(),fixture.serviceId(),new DeployCommand(UUID.randomUUID(),version.id(),0L)));assertCode("RC-DEPLOY-PROMOTION-STALE",()->deployment.deploy(admin,fixture.projectId(),fixture.serviceId(),new DeployCommand(UUID.randomUUID(),version.id(),99L)));var active=deployment.deploy(admin,fixture.projectId(),fixture.serviceId(),new DeployCommand(UUID.randomUUID(),version.id(),workflow.workflow(admin,fixture.projectId(),fixture.serviceId()).promotion().revision()));assertThat(deployment.sandbox(viewer,fixture.projectId(),fixture.serviceId()).environment().activeDeploymentId()).isEqualTo(active.id());assertThat(deployment.evaluate(viewer,fixture.projectId(),fixture.serviceId(),new EvaluationCommand(Map.of("score",mapper.valueToTree(701)))).outputs()).containsKey("approved");var outsiderAccount=users.save(new UserAccount(admin.tenantId(),"deploy-outsider"+UUID.randomUUID()+"@example.test","Deploy Outsider",passwords.encode("CorrectHorseBattery81!"),TenantRole.MEMBER,Instant.now(clock)));var outsider=new RuleCraftPrincipal(outsiderAccount,"acme-rules");assertCode("RC-PROJECT-NOT-FOUND",()->deployment.sandbox(outsider,fixture.projectId(),fixture.serviceId()));}
private EvaluationView evaluate(Fixture fixture,int score){return deployment.evaluate(admin,fixture.projectId(),fixture.serviceId(),new EvaluationCommand(Map.of("score",mapper.valueToTree(score))));}private DecisionVersionService.VersionSummary promote(Fixture fixture,String label){var state=versions.working(admin,fixture.projectId(),fixture.serviceId());var version=versions.capture(admin,fixture.projectId(),fixture.serviceId(),new CaptureCommand(UUID.randomUUID(),label,"Runtime candidate",state.serviceVersion(),state.graphVersion(),state.fingerprint()));var request=workflow.create(admin,fixture.projectId(),fixture.serviceId(),new CreateCommand(UUID.randomUUID(),version.id(),"Deploy "+label,"Runtime sandbox review"));var submitted=workflow.submit(admin,fixture.projectId(),fixture.serviceId(),request.id(),new TransitionCommand(UUID.randomUUID(),request.version(),"Ready"));var approved=workflow.approve(admin,fixture.projectId(),fixture.serviceId(),request.id(),new TransitionCommand(UUID.randomUUID(),submitted.version(),"Approved"));workflow.promote(admin,fixture.projectId(),fixture.serviceId(),request.id(),new TransitionCommand(UUID.randomUUID(),approved.version(),"Promoted"));return version;}private RuleCraftPrincipal member(UUID projectId,String prefix,ProjectRole role){var now=Instant.now(clock);var account=users.save(new UserAccount(admin.tenantId(),prefix+UUID.randomUUID()+"@example.test",prefix+" runtime user",passwords.encode("CorrectHorseBattery80!"),TenantRole.MEMBER,now));projects.upsertMember(admin,projectId,account.getId(),role);return new RuleCraftPrincipal(account,"acme-rules");}private Fixture fixture(){var project=projects.create(admin,key("R"),"Runtime sandbox",null);var service=catalog.createService(admin,project.id(),new DecisionServiceCommand(key("SVC"),"Runtime eligibility",null,List.of(new FieldCommand("score","Score",builtin(BuiltinType.NUMBER),true)),List.of(new FieldCommand("approved","Approved",builtin(BuiltinType.BOOLEAN),true)),null));var graph=graphs.initialize(admin,project.id(),service.id());var nodeId=UUID.randomUUID();var input=port(GraphPortDirection.INPUT,"score",BuiltinType.NUMBER);var output=port(GraphPortDirection.OUTPUT,"approved",BuiltinType.BOOLEAN);var serviceInput=graph.nodes().stream().filter(node->node.kind()==GraphNodeKind.INPUT).findFirst().orElseThrow().ports().getFirst();var serviceOutput=graph.nodes().stream().filter(node->node.kind()==GraphNodeKind.OUTPUT).findFirst().orElseThrow().ports().getFirst();var nodes=new ArrayList<NodeCommand>();graph.nodes().forEach(node->nodes.add(command(node)));nodes.add(new NodeCommand(nodeId,"threshold","Approval threshold",GraphNodeKind.DECISION,null,300,100,List.of(input,output)));graphs.update(admin,project.id(),service.id(),new GraphCommand(graph.version(),nodes,List.of(edge(serviceInput.id(),input.id()),edge(output.id(),serviceOutput.id()))));var expression=expressions.initialize(admin,project.id(),service.id(),nodeId);expressions.update(admin,project.id(),service.id(),nodeId,new ExpressionCommand(expression.version(),"score >= 700"));return new Fixture(project.id(),service.id(),nodeId);}private CatalogService.TypeRefCommand builtin(BuiltinType type){return new CatalogService.TypeRefCommand(type,null);}private PortCommand port(GraphPortDirection direction,String key,BuiltinType type){return new PortCommand(UUID.randomUUID(),direction,key,key,new DecisionGraphService.TypeRefCommand(type,null),true,0);}private NodeCommand command(GraphNodeView node){return new NodeCommand(node.id(),node.nodeKey(),node.name(),node.kind(),node.serviceFieldKey(),node.positionX(),node.positionY(),node.ports().stream().map(port->new PortCommand(port.id(),port.direction(),port.portKey(),port.label(),port.type(),port.required(),port.position())).toList());}private EdgeCommand edge(UUID source,UUID target){return new EdgeCommand(UUID.randomUUID(),source,target);}private String key(String prefix){return prefix+UUID.randomUUID().toString().replace("-","").substring(0,8).toUpperCase();}private void assertCode(String code,Runnable action){assertThatThrownBy(action::run).isInstanceOf(DomainProblemException.class).extracting("code").isEqualTo(code);}private record Fixture(UUID projectId,UUID serviceId,UUID nodeId){}
}
